    def digit_sum(n):
        return sum(int(c) for c in str(n))

    # Compute sum(f(x)) for x in [l, r] efficiently using precomputed ranges
    def compute_digit_sum_range(l, r):
        # We use the property that sum of digit sum up to 10^k - 1
        # is k * 10^(k-1) * 45

        def digit_sum_prefix(x):
            s = 0
            x = int(x)
            m = 10
            digits = len(str(x))

            for i in range(digits - 1, -1, -1):
                d = int(str(x)[i])
                s += d * (m >> (i + 1)) * 45
                if i == 0:
                    break
                end = min(m * (d + 1) - 1, m * d + m - 1)
                s += d * (m >> i)

            return s

        if not r:
            return 0

        return digit_sum_prefix(r) - digit_sum_prefix(l - 1)

    # Search for valid l, r
    max_exp = 20  # we can only set up to 19 digits due to constraint

    def solve():
        for exp in range(1, max_exp):
            base = 10 ** exp
            l = base + 1
            for diff in range(1, 100000):
                r = l + diff - 1
                total = compute_digit_sum_range(l, r)
                if total % a == 0 and l <= r:
                    return str(l) + " " + str(r)
        return None

    result = solve()
    return result

