def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())
    S = lines[1]
    T = lines[2]

    result = []

    # Directional mapping from S to T (what each character maps to)
    s_to_t = {}
    # Directional mapping from T to S (what each character in T came from)
    t_to_s = {}

    for i in range(n - m + 1):
        # Reset mappings for each new substring check
        s_to_t = {}
        t_to_s = {}
        valid = True

        for j in range(m):
            c1 = S[i + j]
            c2 = T[j]

            # Check consistency: S[i+j] should always map to same T[j]
            if c1 in s_to_t:
                if s_to_t[c1] != c2:
                    valid = False
                    break
                # Also ensure T[j] maps back to S[i+j]
                if c2 in t_to_s:
                    if t_to_s[c2] != c1:
                        valid = False
                        break
            else:
                s_to_t[c1] = c2
                t_to_s[c2] = c1

        if valid:
            result.append(i + 1)  # 1-indexed

    result.sort()

    output = f"{len(result)}\n{' '.join(map(str, result))}"
    return output


