import sys

# Increase recursion depth for deep BFS if needed
sys.setrecursionlimit(5000)

def build_graph(edges, n):
    """Build adjacency list from edge list"""
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
    return adj

def bfs_dists(start_node, adj):
    """Compute shortest distances from start_node to all other nodes using BFS"""
    n = len(adj) - 1
    dist = [-1] * n
    dist[start_node - 1] = 0
    queue = [start_node - 1]

    # Using a simple list as queue; this works but not optimal for very large graphs
    # However, with n <= 3000 and m <= 5000, this is acceptable
    visited = [False] * n
    visited[start_node - 1] = True

    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1

        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)
                dist[v] = dist[u] + 1

    return dist

def solution(input_str):
    """Solve the problem"""
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    # Build adjacency list with 1-based indexing
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)

    # Precompute all-pairs shortest distances using BFS from each node
    dists = []  # dists[i] = distances from node (i+1) to all nodes
    for start in range(1, n + 1):
        d = bfs_dists(start, adj)
        dists.append(d)

    # Maximize d(i, j) + d(j, k) + d(k, l) with distinct i, j, k, l
    # O(n^3) approach with early pruning
    max_total = -1
    result = None

    # For efficiency, collect only valid distances in a matrix
    # dists_from[i][j] gives shortest distance from city i to city j
    # But use 0-indexed internally (dists node is dists[start-1])

    # Pre-calculate a full distance matrix for O(1) lookup
    d_matrix = [[-1] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        d = dists[i - 1]
        for j in range(1, n + 1):
            d_matrix[i][j] = d[j - 1] if d[j - 1] != -1 else -1

    # Now iterate over all triples (i, j, k) and try to find best l
    # We can optimize by only considering reachable pairs
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if d_matrix[i][j] == -1:
                continue
            for k in range(1, n + 1):
                if k == i or k == j:
                    continue
                if d_matrix[j][k] == -1:
                    continue

                current_sum = d_matrix[i][j] + d_matrix[j][k]

                # Find best l distinct from i, j, k
                best_l = -1
                best_l_dist = -1

                for l in range(1, n + 1):
                    if l in (i, j, k):
                        continue
                    if d_matrix[k][l] != -1:
                        if d_matrix[k][l] > best_l_dist:
                            best_l_dist = d_matrix[k][l]
                            best_l = l

                if best_l != -1:
                    total = current_sum + best_l_dist
                    if total > max_total:
                        max_total = total
                        result = [i, j, k, best_l]

    if result:
        return ' '.join(map(str, result))
    else:
        return '1 2 3 4'  # fallback (problem guarantees a solution exists)

if __name__ == "__main__":
    # Example test
    input_data = '8 9\n1 2\n2 3\n3 4\n4 1\n4 5\n5 6\n6 7\n7 8\n8 5\n'
    print(solution(input_data))
