    for tri in tri_list:
        edges = {
            (min(tri[0], tri[1]), max(tri[0], tri[1])),
            (min(tri[1], tri[2]), max(tri[1], tri[2])),
            (min(tri[0], tri[2]), max(tri[0], tri[2]))
        }
        tri_edge_sets.append(edges)

    # Build adjacency
    adj = [[] for _ in range(len(tri_list))]
    for i in range(len(tri_list)):
        for j in range(i + 1, len(tri_list)):
            if tri_edge_sets[i] & tri_edge_sets[j]:
                adj[i].append(j)
                adj[j].append(i)

    # Sort by importance
    imp_list = sorted([(sum(tri), tri) for tri in tri_list])

    # Greedy coloring
    vertex_colors = {}
    for _, tri in imp_list:
        idx = tri_list.index(tri)
        used = set()
        for nb in adj[idx]:
            if vertex_colors.get(tri_list[nb]):
                used.add(vertex_colors[tri_list[nb]])
        color = 1
        while color in used:
            color += 1
        vertex_colors[tri] = color

    result = [vertex_colors[tri] for _, tri in imp_list]
    return ' '.join(map(str, result)) + '\n'
