        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append((v, i))
            adj[v].append((u, i))

    INF = float('inf')

    # dp[u][sz][has_k] = min cuts in subtree u where u belongs to component of size sz
    # has_k = 0 means no k-sized component in subtree, 1 means k-sized component exists
    # dp values: menu for sz=1..k, has_k=0..1

    @memoize
    def dfs(u, p, subtree_size):
        cur_dp = [[INF] * 2 for _ in range(subtree_size + 1)]
        cur_dp[1][0] = 0  # Initial: component of size 1, no k-size yet
        sz = 1

        for v, idx in adj[u]:
            if v == p:
                continue
            child_sz, child_dp, child_res = dfs(v, u)

            new_dp = [[INF] * 2 for _ in range(child_sz + 1)]
            has_k_so_far = False

            # For each child, decide to cut or keep edge
            for old_sz in range(1, sz + 1):
                if cur_dp[old_sz][0] == INF and cur_dp[old_sz][1] == INF:
                    continue
                for new_sz in range(1, child_sz + 1):
                    for sk in range(2):
                        for ok in range(2):
                            # Keep edge (same component)
                            if old_sz + new_sz <= k:
                                found_k = (old_sz + new_sz == k)
                                new_has_k = -1 if found_k else (ok or sk)
                                cost = cur_dp[old_sz][ok] + child_dp[new_sz][sk]
                                if cost < INF:
                                    new_dp[old_sz + new_sz][new_has_k] = min(
                                        new_dp[old_sz + new_sz][new_has_k], cost
