                            # Cut edge (new component from child)
                            if ok == 0 or child_dp[new_sz][0] == INF:
                                continue
                            found_k = (ok == 1 and old_sz + new_sz == k)
                            new_has_k = 1 if found_k else (ok or sk)
                            cost = cur_dp[old_sz][ok] + child_dp[new_sz][sk]
                            if cost < INF:
