    flow = [[0] * (n + 2) for _ in range(n + 2)]
    adj = [[] for _ in range(n + 2)]

    INF = 10**9

    def add_edge(u, v, c):
        adj[u].append([v, c, len(adj[v])])
        adj[v].append([u, 0, len(adj[u]) - 1])

    for i in range(n):
        add_edge(S, i + 1, a[i])

    for i in range(n):
        add_edge(i + 1, T, b[i])

    for i in range(m):
        u, v = map(int, lines[3 + i].split())
        add_edge(u, v, INF)
        add_edge(v, u, INF)

    level = [-1] * (n + 2)

    def bfs():
        for i in range(n + 2):
            level[i] = -1
        level[S] = 0
        queue = [S]
        while queue:
            u = queue.pop(0)
            for v, c, _ in adj[u]:
                if c - flow[u][v] > 0 and level[v] == -1:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[T] != -1

    def dfs(u, f, ptr):
        if f == 0 or u == T:
            return f
        for i in range(ptr[u], len(adj[u])):
            ptr[u] = i
            v, c, rev = adj[u][i]
            if level[v] != level[u] + 1 or c - flow[u][v] == 0:
                continue
            pushed = dfs(v, min(f, c - flow[u][v]), ptr)
            if pushed == 0:
                continue
            flow[u][v] += pushed
            flow[v][rev] -= pushed
            return pushed
        return 0

    max_flow = 0
    while bfs():
        ptr = [0] * (n + 2)
        while True:
            pushed = dfs(S, INF, ptr)
            if pushed == 0:
                break
            max_flow += pushed

    if max_flow != sum(a):
        return "NO"

    ans = [[0] * n for _ in range(n)]

