    # Build conflict graph: conflict[i][j] = True if friends i and j conflict
    # Two friends conflict if they both visit in the same type 1 interval
    conflict = [[False] * num_friends for _ in range(num_friends)]

    for i in range(len(type1_indices) - 1):
        start = type1_indices[i]
        end = type1_indices[i + 1]

        friends_in_interval = set()
        for j in range(start, end):
            if events[j][0] == 2:
                friend = events[j][1]
                friends_in_interval.add(friend)

        idx = {}
        for f in friends_in_interval:
            idx[f] = friend_to_idx[f]

        # All friends in same interval conflict
        fl = list(friends_in_interval)
        for k in range(len(fl)):
            for l in range(k + 1, len(fl)):
                conflict[idx[fl[k]]][idx[fl[l]]] = True
                conflict[idx[fl[l]]][idx[fl[k]]] = True

    # Find Maximum Independent Set using backtracking with pruning
