    for i in range(num_friends):
        cnt = sum(conflict[i])
        if cnt > max_conflict_size:
            max_conflict_size = cnt

    def dfs(idx, count, used_mask):
        nonlocal ans

        if idx == num_friends:
            ans = max(ans, count)
            return

        # Pruning: if remaining friends can't beat current answer, stop
        if count + (num_friends - idx) <= ans:
            return

        current_friend = friend_list[idx] if idx < num_friends else -1

        # Try including idx if it doesn't conflict with used graph
