            for j in range(idx):
                if (used_mask >> j) & 1:
                    if conflict[j][idx]:
                        conflicts_with_used += 1

            if conflicts_with_used == 0:
                dfs(idx + 1, count + 1, used_mask | (1 << idx))
                return

        dfs(idx + 1, count, used_mask)

    friend_list = sorted([f for f in friend_to_idx.keys()])

    def max_independent_set(mask):
        nonlocal ans
        if mask == 0:
            return

        ans = max(ans, bin(mask).count('1'))

        # Try removing any friend from conflict
        i = 0
        while i < num_friends:
            if (mask >> i) & 1:
                # friend i is selected - check if removing helps
                remaining = mask & ~(1 << i)
                if i >= ans:
                    ans = max(ans, max_independent_set(remaining))
            i += 1
            if i >= ans:
                break

        # More efficient: greedy pruning
        if ans >= num_friends - (mask.bit_length() - mask & (mask - 1)):
            return

    # Simple BFS for maximum independent set
    for count in range(num_friends, 0, -1):
        found = False
        for mask in range(1 << num_friends):
            if bin(mask).count('1') != count:
                continue

            valid = True
            for i in range(num_friends):
                if (mask >> i) & 1:
                    for j in range(i + 1, num_friends):
                        if conflict[i][j]:
                            if (mask >> j) & 1:
                                valid = False
                                break
                    if not valid:
                        break

            if valid:
                ans = count
                found = True
                break

        if found:
            return str(ans)

