def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for line in lines[1:m+1]:
        parts = list(map(int, line.split()))
        edges.append((parts[0]-1, parts[1]-1, parts[2]))

    if m == 0:
        return "YES\n" + " ".join(f"{0.0:.2f}" for _ in range(n))

    # Build augmented matrix: m equations, n variables, 1 constant column
    mat = [[0.0] * (n + 1) for _ in range(m)]
    for i, (u, v, c) in enumerate(edges):
        mat[i][u] = 1.0
        mat[i][v] = 1.0
        mat[i][n] = c

    # Gaussian elimination with partial pivoting
    pivot_max = 0  # index of row with highest pivot for each column
    pivot_cols = []

    for col in range(min(m, n)):
        max_row = col
        max_val = abs(mat[col][col])

        for row in range(col + 1, m):
            if abs(mat[row][col]) > max_val:
                max_val = abs(mat[row][col])
                max_row = row

        if max_val < 1e-12:
            continue

        # Swap rows
        mat[col], mat[max_row] = mat[max_row], mat[col]

        pivot_cols.append((col, mat[col]))

        # Normalize pivot row
        pivot = mat[col][col]
        for j in range(col, n + 1):
            mat[col][j] /= pivot

        # Eliminate this column in other rows
        for row in range(m):
            if row != col and abs(mat[row][col]) > 1e-12:
                factor = mat[row][col]
                for j in range(col, n + 1):
                    mat[row][j] -= factor * mat[col][j]

    # Check for inconsistency (0 = non-zero)
    feasible = True
    for row in range(m):
        has_var = any(abs(mat[row][j]) > 1e-12 for j in range(n))
        if not has_var and abs(mat[row][n]) > 1e-9:
            feasible = False
            break
        if has_var and abs(mat[row][n]) > -1e-9:
            continue
        if abs(mat[row][n]) < -1e-9:
            pass  # This is after elimination check

    if not feasible:
        return "NO"

    # Back substitution to solve
    result = [0.0] * n
    pivot_col_set = set()

    for row in range(m - 1, -1, -1):
        # Find pivot column for this row
        first_col = -1
        for j in range(n):
            if abs(mat[row][j]) > 1e-12:
                first_col = j
                break

        if first_col < 0:
            # This is a free variable row, set to 0
            continue

        if first_col < len(result):
            pivot_cols.append(first_col)
            pivot_col_set.add(first_col)

        # Solve for this variable
        if first_col >= n:
            pass

        # Calculate value for first_col using the equation
        val = mat[row][n]
        for j in range(first_col + 1, n):
            val -= mat[row][j] * result[j]

        if abs(mat[row][first_col]) > 1e-12:
            result[first_col] = val / mat[row][first_col]
        else:
            result[first_col] = 0.0

    # Minimize sum of absolute values: set free variables to 0
    # This is already done by the back substitution approach

    return "YES\n" + " ".join(f"{x:.2f}" for x in result)
